      SUBROUTINE DBEND3CC     CALCULATES PARTIAL DERIVATIVES OF THE THIRD-ORDERC     TRANSFER MATRIX OF A BENDING MAGNETC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'HSINT3.CIN'      INCLUDE 'HPINT3.CIN'      INCLUDE 'INDBND.CIN'      INCLUDE 'U.CIN'      INCLUDE 'VSINT3.CIN'      INCLUDE 'VPINT3.CIN'C-------------------------------------------------------------------------------C      IF (JV .NE. NGAM .AND. JV .NE. NK3) GO TO 100      IF (H0 .EQ. 0) GO TO 100      DGAB = DPARM/(H0*UNITI(1))**3      IF (JV .EQ. NK3) DGAB = DGAB/(H0*UNITI(8))**4      UV(1,1) = - DGAB*H0**4*HSCCC0      UV(1,2) = - 3.0*DGAB*H0**4*HSCCS0      UV(1,3) = - 3.*DGAB*H0**4*HSCSS0      UV(1,4) = - DGAB*H0**4*HSSSS0      UV(1,8) = 3.0*DGAB*H0**4*HSCCC2      UV(1,9) = 3.0*DGAB*H0**4*HSSCC2      UV(1,14) = 6.0*DGAB*H0**4*HSCCS2      UV(1,15) = 6.0*DGAB*H0**4*HSSCS2      UV(1,17) = 3.0*DGAB*H0**4*HSCSS2      UV(1,18) = 3.0*DGAB*H0**4*HSSSS2      UV(1,36) = - 3.0*DGAB*H0**4*HSCCD0      UV(1,37) = - 6.0*DGAB*H0**4*HSCSD0      UV(1,38) = - 3.0*DGAB*H0**4*HSSSD0      UV(1,41) = 3.0*DGAB*H0**4*HSDCC2      UV(1,44) = 6.0*DGAB*H0**4*HSDCS2      UV(1,45) = 3.0*DGAB*H0**4*HSDSS2      UV(1,51) = - 3.0*DGAB*H0**4*HSCDD0      UV(1,52) = - 3.0*DGAB*H0**4*HSSDD0      UV(1,56) = - DGAB*H0**4*HSDDD0C      UV(2,1) = - DGAB*H0**4*HPCCC0      UV(2,2) = - 3.0*DGAB*H0**4*HPCCS0      UV(2,3) = - 3.0*DGAB*H0**4*HPCSS0      UV(2,4) = - DGAB*H0**4*HPSSS0      UV(2,8) = 3.0*DGAB*H0**4*HPCCC2      UV(2,9) = 3.0*DGAB*H0**4*HPSCC2      UV(2,14) = 6.0*DGAB*H0**4*HPCCS2      UV(2,15) = 6.0*DGAB*H0**4*HPSCS2      UV(2,17) = 3.0*DGAB*H0**4*HPCSS2      UV(2,18) = 3.0*DGAB*H0**4*HPSSS2      UV(2,36) = - 3.0*DGAB*H0**4*HPCCD0      UV(2,37) = - 6.0*DGAB*H0**4*HPCSD0      UV(2,38) = - 3.0*DGAB*H0**4*HPSSD0      UV(2,41) = 3.0*DGAB*H0**4*HPDCC2      UV(2,44) = 6.0*DGAB*H0**4*HPDCS2      UV(2,45) = 3.0*DGAB*H0**4*HPDSS2      UV(2,51) = - 3.0*DGAB*H0**4*HPCDD0      UV(2,52) = - 3.0*DGAB*H0**4*HPSDD0      UV(2,56) = - DGAB*H0**4*HPDDD0C      UV(3,5) = 3.0*DGAB*H0**4*VSCCC1      UV(3,6) = 6.0*DGAB*H0**4*VSCSC1      UV(3,7) = 3.0*DGAB*H0**4*VSSSC1      UV(3,10) = - DGAB*H0**4*VSCCC3      UV(3,11) = 3.0*DGAB*H0**4*VSCCS1      UV(3,12) = 6.0*DGAB*H0**4*VSCSS1      UV(3,13) = 3.0*DGAB*H0**4*VSSSS1      UV(3,16) = - 3.0*DGAB*H0**4*VSCCS3      UV(3,19) = - 3.0*DGAB*H0**4*VSCSS3      UV(3,20) = - DGAB*H0**4*VSSSS3      UV(3,39) = 6.0*DGAB*H0**4*VSCDC1      UV(3,40) = 6.0*DGAB*H0**4*VSSDC1      UV(3,42) = 6.0*DGAB*H0**4*VSCDS1      UV(3,43) = 6.0*DGAB*H0**4*VSSDS1      UV(3,53) = 3.0*DGAB*H0**4*VSDDC1      UV(3,54) = 3.0*DGAB*H0**4*VSDDS1C      UV(4,5) = 3.0*DGAB*H0**4*VPCCC1      UV(4,6) = 6.0*DGAB*H0**4*VPCSC1      UV(4,7) = 3.0*DGAB*H0**4*VPSSC1      UV(4,10) = - DGAB*H0**4*VPCCC3      UV(4,11) = 3.0*DGAB*H0**4*VPCCS1      UV(4,12) = 6.0*DGAB*H0**4*VPCSS1      UV(4,13) = 3.0*DGAB*H0**4*VPSSS1      UV(4,16) = - 3.0*DGAB*H0**4*VPCCS3      UV(4,19) = - 3.0*DGAB*H0**4*VPCSS3      UV(4,20) = - DGAB*H0**4*VPSSS3      UV(4,39) = 6.0*DGAB*H0**4*VPCDC1      UV(4,40) = 6.0*DGAB*H0**4*VPSDC1      UV(4,42) = 6.0*DGAB*H0**4*VPCDS1      UV(4,43) = 6.0*DGAB*H0**4*VPSDS1      UV(4,53) = 3.0*DGAB*H0**4*VPDDC1      UV(4,54) = 3.0*DGAB*H0**4*VPDDS1C  100 RETURN      END